#include "connection_manager.hpp"
#include "json_value.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <stdexcept>

static std::string read(const std::filesystem::path& path){std::ifstream input(path,std::ios::binary);return std::string((std::istreambuf_iterator<char>(input)),{});}

int main(int argc,char** argv){try{if(argc<2)throw std::runtime_error("missing MCP executable");auto root=std::filesystem::temp_directory_path()/"kr_mycelia_connection_manager";std::filesystem::create_directories(root);auto json=root/"mcp.json",claude=root/"claude_desktop_config.json",toml=root/"config.toml";{std::ofstream out(json);out<<"{\"mcpServers\":{\"foreign\":{\"command\":\"keep.exe\"}},\"setting\":true}";}{std::ofstream out(claude);out<<"{\"mcpServers\":{\"foreign\":{\"command\":\"keep.exe\"}}}";}{std::ofstream out(toml);out<<"model = \"keep-model\"\n[mcp_servers.foreign]\ncommand = \"keep.exe\"\n";}const std::string token(64,'a');krmemory::connect_client(krmemory::ClientKind::cursor,json,argv[1],"cursor-test",token);krmemory::connect_client(krmemory::ClientKind::claude_desktop,claude,argv[1],"claude-test",token);krmemory::connect_client(krmemory::ClientKind::codex,toml,argv[1],"codex-test",token);auto j=read(json),c=read(claude),t=read(toml);if(j.find("foreign")==std::string::npos||j.find("kr-mycelia-memory")==std::string::npos||c.find("kr-mycelia-memory")==std::string::npos||j.find(token)!=std::string::npos||c.find(token)!=std::string::npos)throw std::runtime_error("JSON merge or token protection failed");if(t.find("mcp_servers.foreign")==std::string::npos||t.find("mcp_servers.kr_mycelia_memory")==std::string::npos||t.find(token)!=std::string::npos)throw std::runtime_error("TOML merge or token protection failed");krmemory::disconnect_client(krmemory::ClientKind::cursor,json,"cursor-test");krmemory::disconnect_client(krmemory::ClientKind::claude_desktop,claude,"claude-test");krmemory::disconnect_client(krmemory::ClientKind::codex,toml,"codex-test");j=read(json);c=read(claude);t=read(toml);if(j.find("foreign")==std::string::npos||j.find("kr-mycelia-memory")!=std::string::npos||c.find("foreign")==std::string::npos||c.find("kr-mycelia-memory")!=std::string::npos||t.find("mcp_servers.foreign")==std::string::npos||t.find("mcp_servers.kr_mycelia_memory")!=std::string::npos)throw std::runtime_error("disconnect did not preserve foreign configuration");std::filesystem::remove_all(root);std::cout<<"PASS: transactional Cursor/Claude JSON and Codex TOML merge, protected credentials and clean disconnect\n";return 0;}catch(const std::exception& error){std::cerr<<"FAIL: "<<error.what()<<'\n';return 1;}}
